import Foundation

extension Deck {
    /// The Suit of Swords — air, intellect, truth, conflict, and the mind. Ids 50...63.
    static let swords: [TarotCard] = [
        TarotCard(id: 50, name: "Ace of Swords", arcana: .minor, suit: .swords, number: 1, element: .air,
                  keywords: ["clarity", "truth", "breakthrough", "new idea"],
                  upright: "A breakthrough of mental clarity and piercing truth. Cut through confusion and speak what is real.",
                  reversed: "Clouded thinking, confusion, or truth misused. Wait for clarity before wielding sharp words or decisions."),
        TarotCard(id: 51, name: "Two of Swords", arcana: .minor, suit: .swords, number: 2, element: .air,
                  keywords: ["stalemate", "indecision", "avoidance", "blocked emotions"],
                  upright: "A tense stalemate where you avoid a hard choice. Remove the blindfold and face the decision honestly.",
                  reversed: "The deadlock breaks and clarity returns. A long-avoided truth finally comes into view."),
        TarotCard(id: 52, name: "Three of Swords", arcana: .minor, suit: .swords, number: 3, element: .air,
                  keywords: ["heartbreak", "sorrow", "grief", "painful truth"],
                  upright: "Heartbreak and the sharp pain of a difficult truth. Let yourself grieve — clarity and healing follow honest sorrow.",
                  reversed: "Releasing pain and beginning to heal. Forgiveness loosens the grip of an old wound."),
        TarotCard(id: 53, name: "Four of Swords", arcana: .minor, suit: .swords, number: 4, element: .air,
                  keywords: ["rest", "recovery", "stillness", "contemplation"],
                  upright: "A needed pause for rest, recovery, and quiet contemplation. Step back and let your mind recuperate.",
                  reversed: "Restlessness or burnout from refusing to rest. Heed the call to slow down before exhaustion forces it."),
        TarotCard(id: 54, name: "Five of Swords", arcana: .minor, suit: .swords, number: 5, element: .air,
                  keywords: ["conflict", "defeat", "winning at a cost", "discord"],
                  upright: "A hollow victory won through conflict that leaves resentment behind. Ask whether being right is worth the cost.",
                  reversed: "Reconciliation, making amends, or walking away from a fight. Choose peace over a pointless win."),
        TarotCard(id: 55, name: "Six of Swords", arcana: .minor, suit: .swords, number: 6, element: .air,
                  keywords: ["transition", "moving on", "recovery", "passage"],
                  upright: "A gradual move toward calmer waters and away from trouble. The transition is hard but leads to healing.",
                  reversed: "Resisting a needed change or carrying old baggage along. You can't move on while clutching the past."),
        TarotCard(id: 56, name: "Seven of Swords", arcana: .minor, suit: .swords, number: 7, element: .air,
                  keywords: ["strategy", "deception", "stealth", "getting away"],
                  upright: "Cleverness, strategy, and acting alone — sometimes at the edge of honesty. Be sure your tactics match your values.",
                  reversed: "A deception exposed, or a decision to come clean. Honesty restores trust the shortcuts eroded."),
        TarotCard(id: 57, name: "Eight of Swords", arcana: .minor, suit: .swords, number: 8, element: .air,
                  keywords: ["restriction", "self-limiting beliefs", "feeling trapped", "fear"],
                  upright: "Feeling trapped by fear and self-limiting beliefs more than by real bars. Look closely — the way out is nearer than it seems.",
                  reversed: "Freeing yourself from a mental prison. You see the escape and reclaim your own power."),
        TarotCard(id: 58, name: "Nine of Swords", arcana: .minor, suit: .swords, number: 9, element: .air,
                  keywords: ["anxiety", "worry", "fear", "sleepless nights"],
                  upright: "Anxiety and worry that loom larger in the dark than in daylight. Name the fears; most are heavier in your mind than in life.",
                  reversed: "Worry beginning to lift as you reach for help. The worst of the anxiety releases its grip."),
        TarotCard(id: 59, name: "Ten of Swords", arcana: .minor, suit: .swords, number: 10, element: .air,
                  keywords: ["rock bottom", "endings", "release", "painful conclusion"],
                  upright: "A painful but final ending — rock bottom, with nowhere to go but up. The worst is over; a new dawn is coming.",
                  reversed: "Recovery, survival, and slow rising after a hard ending. You endured; resist the relapse into despair."),
        TarotCard(id: 60, name: "Page of Swords", arcana: .minor, suit: .swords, number: 11, element: .air,
                  keywords: ["curiosity", "ideas", "vigilance", "communication"],
                  upright: "A sharp, curious mind eager for new ideas and truth. Ask questions and speak up — just choose your words with care.",
                  reversed: "Gossip, scattered thinking, or all talk. Slow down and make sure your facts and intentions are sound."),
        TarotCard(id: 61, name: "Knight of Swords", arcana: .minor, suit: .swords, number: 12, element: .air,
                  keywords: ["ambition", "drive", "directness", "haste"],
                  upright: "Fast-moving ambition and direct, fearless action. Charge toward your goal with focus and conviction.",
                  reversed: "Recklessness, bluntness, or rushing in unprepared. Slow your charge before it causes collateral damage."),
        TarotCard(id: 62, name: "Queen of Swords", arcana: .minor, suit: .swords, number: 13, element: .air,
                  keywords: ["clarity", "honesty", "independence", "discernment"],
                  upright: "Clear-eyed honesty, independence, and sharp discernment. Speak your truth directly and set firm boundaries.",
                  reversed: "Coldness, harshness, or bitterness clouding judgment. Soften the edge and let compassion temper your clarity."),
        TarotCard(id: 63, name: "King of Swords", arcana: .minor, suit: .swords, number: 14, element: .air,
                  keywords: ["intellect", "authority", "truth", "fairness"],
                  upright: "Authority grounded in clear thought, truth, and fair judgment. Lead with logic, integrity, and a level head.",
                  reversed: "Cold logic, manipulation, or misuse of power. Ensure your reasoning serves truth, not just your own advantage.")
    ]
}
